ROOT=Path(__file__).resolve().parents[1]
with sync_playwright() as p:
 b=p.webkit.launch(executable_path=os.environ['PLAYWRIGHT_WEBKIT_EXECUTABLE']) if os.getenv('GIF_TEST_BROWSER')=='webkit' else p.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox'])
 c=b.new_context(viewport={'width':390,'height':844})
 def route(r):
  u=urlparse(r.request.url);f=ROOT/u.path.lstrip('/')
  if f.is_dir():f/='index.html'
  if u.hostname=='edit.test' and f.is_file():r.fulfill(body=f.read_bytes(),content_type={'.js':'application/javascript','.css':'text/css','.json':'application/json'}.get(f.suffix,'text/html'))
  else:r.fulfill(status=404)
 c.route('**/*',route);page=c.new_page();errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.goto('https://edit.test/');page.evaluate('TreinoStorage.ready');page.evaluate('localStorage.setItem("treinoAlunos",JSON.stringify([{nome:"Teste edição",student_id:"edit",treino:{A:["Glúteo Na Polia — 3×12 Cada Perna [Vídeo: https://youtu.be/KeepTEST123] [GIFs: https://drive.google.com/file/d/keepGIF/view]"]},titulos:{A:"A. Glúteos"}}]))');page.reload();page.evaluate('TreinoStorage.ready');row=page.locator('.sec-a ol>li').first;row.evaluate("e=>{const b=e.querySelector('.bold');b.textContent='Mesa Flexora';const media=[...e.querySelectorAll('.exercise-video,.exercise-videos,.exercise-gifs')].map(n=>n.cloneNode(true));e.replaceChildren(b,document.createTextNode(' unilateral — 3×15 Com 3s Na Descida.'),...media);e.dispatchEvent(new InputEvent('input',{bubbles:true,inputType:'insertText',data:'unilateral'}));}");assert row.locator('.bold').first.inner_text()=='Mesa Flexora';page.locator('#workoutGifsBtn').click();main=page.locator('#workoutGifDialog');expect(main.locator('.gif-exercise-name').first).to_have_text('1. Mesa Flexora unilateral');dose=main.locator('.gif-card-text>p').first.inner_text();assert 'unilateral' not in dose and '3×15 Com 3s Na Descida.' in dose;main.get_by_role('button',name='✎ Editar',exact=True).first.click();edit=page.get_by_role('dialog',name='Editar exercício na ficha');expect(edit.get_by_role('textbox',name='Nome do exercício',exact=True)).to_have_value('Mesa Flexora unilateral');edit.get_by_role('button',name='Cancelar',exact=True).click();main.get_by_role('button',name='Fechar',exact=True).click();page.locator('#pdfBtn').click();expect(page.locator('#pdfBody .pdf-ex-title').first).to_have_text('Mesa Flexora unilateral');assert 'unilateral' not in page.locator('#pdfBody .pdf-ex-details').first.inner_text();page.locator('#closePdfViewer').click();assert 'Mesa Flexora unilateral' in row.inner_text();assert row.locator('.bold').first.inner_text()=='Mesa Flexora';assert not errors,errors;b.close();print('PASS: manually unbolded unilateral remains part of full GIF/PDF exercise name, dose separated, original bold styling unchanged')
